import re
from datetime import datetime, timedelta

# Recompute streak from existing notes_meta and access_token

date_pattern = re.compile(r'(\d{4}-\d{2}-\d{2})')
items=[]
for n in notes_meta:
    m=date_pattern.search(n.get('title',''))
    if not m:
        continue
    d=datetime.strptime(m.group(1),'%Y-%m-%d').date()
    items.append((d,n['note_id']))
items.sort(key=lambda x:x[0])

map_val={}
for d,note_id in items:
    note=apis.simple_note.show_note(access_token=access_token,note_id=note_id)
    content=note.get('content','')
    m=re.search(r'^practiced_good_posture\s*:\s*(yes|no)\s*$',content,flags=re.MULTILINE|re.IGNORECASE)
    map_val[d]=m.group(1).lower() if m else None

sorted_dates=sorted(map_val.keys())
longest=0
best_intervals=[]
current=0
start=None
prev=None
for d in sorted_dates:
    if map_val[d]=='yes':
        if start is None:
            start=d
            current=1
        else:
            if prev is not None and d==prev+timedelta(days=1):
                current+=1
            else:
                # finalize previous interval
                if current>longest:
                    longest=current
                    best_intervals=[(start,prev)]
                elif current==longest and current!=0:
                    best_intervals.append((start,prev))
                start=d
                current=1
        prev=d
    else:
        if start is not None:
            if current>longest:
                longest=current
                best_intervals=[(start,prev)]
            elif current==longest and current!=0:
                best_intervals.append((start,prev))
        start=None
        prev=None
        current=0

# finalize
if start is not None:
    if current>longest:
        longest=current
        best_intervals=[(start,prev)]
    elif current==longest and current!=0:
        best_intervals.append((start,prev))

print('longest_streak_days:',longest)
print('best_intervals:',[(a.isoformat(),b.isoformat(),(b-a).days+1) for a,b in best_intervals])

